/* Position the Volt nav bar at top of the editor host */
.volt-nav-bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    z-index: 100;
    height: 36px;
    display: flex;
    align-items: center;
    padding: 0 8px;
    gap: 2px;
    background: #1e1e1e;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}
.volt-nav-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 0 12px;
    height: 26px;
    border: none;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    -webkit-user-select: none;
            user-select: none;
    white-space: nowrap;
    background: transparent;
    color: #cccccc;
    transition: background 0.12s;
}
.volt-nav-btn mat-icon {
    font-size: 15px;
    width: 15px;
    height: 15px;
    line-height: 15px;
}
.volt-nav-btn:hover { background: rgba(255,255,255,0.08); }
.volt-nav-btn--active { background: #0e639c !important; color: #fff !important; cursor: default; }
.volt-nav-btn--active:hover { background: #0e639c !important; }
