  display: block;
  height: 100%;
}
:host .header-panel {
  background-color: var(--headerBackground);
  color: var(--headerColor);
  position: absolute;
  top: 0px;
  left: 0px;
  height: 36px;
  width: 100%;
  text-align: center;
  line-height: 36px;
  border-bottom: 1px solid var(--headerBorder);
}
:host .header-panel mat-icon {
  display: inline-block;
  vertical-align: middle;
}
:host .header-panel span {
  margin-left: 10px;
}
:host .work-panel {
  position: absolute;
  top: 37px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  background-color: var(--workPanelBackground);
  overflow: hidden;
}
:host .container {
  height: 100%;
  overflow-y: auto;
}
:host .mat-column-select {
  overflow: visible;
  flex: 0 0 80px;
}
:host .mat-column-name {
  flex: 1 1 180px;
}
:host .mat-column-key {
  flex: 1 1 360px;
}
:host .key-cell {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}
