  flex: 1;
  word-break: break-all;
  font-family: "Roboto Mono", monospace;
}
:host .mat-column-description {
  flex: 1 1 140px;
}
:host .mat-column-created {
  flex: 1 1 100px;
}
:host .mat-column-expires {
  flex: 1 1 100px;
}
:host .mat-column-enabled {
  flex: 1 1 80px;
}
:host .mat-column-remove {
  flex: 0 0 60px;
}
:host .mat-cell,
:host .mat-mdc-cell,
:host .mdc-data-table__cell {
  font-size: 13px;
  border-top: none !important;
  border-bottom: 1px solid rgb(81, 81, 81) !important;
}
:host .mat-row,
:host .mat-mdc-row,
:host .my-mat-row {
  border-top: none !important;
  border-bottom: none !important;
}
:host .mat-header-row,
:host .mat-mdc-header-row {
  top: 0;
  position: sticky;
  z-index: 10;
  background-color: var(--workPanelBackground);
}
:host .mat-header-cell {
  font-size: 15px;
  position: sticky;
  top: 0;
  z-index: 11;
  background-color: var(--workPanelBackground);
