n}\n.month-btn.active {\n    background: var(--scheduler-accent-color, #556e82);\n    color: var(--scheduler-secondary-text-color, #ffffff);\n    border-color: var(--scheduler-accent-color, #556e82);\n}\n.month-btn:hover {\n    background: var(--scheduler-hover-bg, #e0e0e0);\n    color: var(--scheduler-text-color, #333333);\n}\n.month-btn.active:hover {\n    background: var(--scheduler-accent-color, #556e82);\n    color: var(--scheduler-secondary-text-color, #ffffff);\n    opacity: 0.9;\n}\n\n// Month indicator for calendar popup (non-interactive)\n.month-indicator {\n    flex: 1;\n    padding: 8px 4px;\n    border: 1px solid #ccc;\n    background: #f9f9f9;\n    color: var(--scheduler-text-color, #333333);\n    border-radius: 3px;\n    font-size: 11px;\n    font-weight: 500;\n    margin: 2px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    min-width: 40px;\n    max-width: 50px;\n}\n\n// Active state for month indicator\n.month-indicator[style*=\"background: #556e82\"] {\n    background: var(--scheduler-accent-color, #556e82) !important;\n    color: var(--scheduler-secondary-text-color, #ffffff) !important;\n    border-color: var(--scheduler-accent-color, #556e82) !important;\n}\n\n// Responsive toggle row\n.toggle-row-responsive {\n  display: flex;\n  gap: 16px;\n  align-items: center;\n  margin-bottom: 12px;\n  flex-wrap: wrap;\n  justify-content: center;\n}\n\n.toggle-item {\n  min-width: 120px;\n  flex: 1 1 120px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.day-of-month-btn {\n    aspect-ratio: 1;\n    border-radius: 50%;\n    padding: 0;\n    margin: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 11px;\n    font-weight: 500;\n    background: #f9f9f9;\n    color: var(--scheduler-text-color, #333333);\n    border: 1px solid #ccc;\n    cursor: pointer;\n    transition: background 0.2s, color 0.2s;\n    width: 100%;\n    min-width: 24px;\n    max-width: 100%;\n}\n\n@media (min-width: 768px) {\n    .day-of-month-btn {\n        font-size: 12px;\n    }\n}\n\n@media (min-width: 1200px) {\n    .day-of-month-btn {\n        font-size: 13px;\n    }\n}\n.day-of-month-btn.active {\n    background: var(--scheduler-accent-color, #556e82);\n    color: var(--scheduler-secondary-text-color, #ffffff);\n    border-color: var(--scheduler-accent-color, #556e82);\n}\n.day-of-month-btn:hover {\n    background: var(--scheduler-hover-bg, #e0e0e0);\n    color: var(--scheduler-text-color, #333333);\n}\n.day-of-month-btn.active:hover {\n    background: var(--scheduler-accent-color, #556e82);\n    color: var(--scheduler-secondary-text-color, #ffffff);\n    opacity: 0.9;\n}\n\n// Day indicator for calendar popup (non-interactive)\n.day-indicator {\n    aspect-ratio: 1;\n    border-radius: 50%;\n    padding: 0;\n    margin: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 11px;\n    font-weight: 500;\n    background: #f9f9f9;\n    color: var(--scheduler-text-color, #333333);\n    border: 1px solid #ccc;\n    width: 32px;\n    height: 32px;\n    min-width: 32px;\n}\n\n// Active state for day indicator\n.day-indicator[style*=\"background: #556e82\"] {\n    background: var(--scheduler-accent-color, #556e82) !important;\n    color: var(--scheduler-secondary-text-color, #ffffff) !important;\n    border-color: var(--scheduler-accent-color, #556e82) !important;\n}\n\n.day-btn.round-btn {\n    border-radius: 50%;\n    width: 32px;\n    height: 32px;\n    padding: 0;\n    margin: 2px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 14px;\n    background: #f9f9f9;\n    color: var(--scheduler-text-color, #333333);\n    border: 1px solid #ccc;\n    cursor: pointer;\n    transition: background 0.2s, color 0.2s;\n}\n.day-btn.round-btn:hover {\n    background: var(--scheduler-hover-bg, #e0e0e0);\n    color: var(--scheduler-text-color, #333333);\n}\n.day-btn.