  display: flex;
  flex-direction: column;
  min-height: 172px;
  padding: 10px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: #313435;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03), 0 10px 26px rgba(0, 0, 0, 0.16);
  color: rgba(255, 255, 255, 0.92);
}
