import { DOCUMENT } from '@angular/common';
import { Inject, Injectable } from '@angular/core';
import { THEMES } from '../_config/theme.config';

@Injectable({
    providedIn: 'root'
})
export class ThemeService {
    private voltOverrides: Record<string, string> | null = null;
    // Maps VS Code CSS variable names to FUXA theme variable names
    private static readonly VSCODE_TO_FUXA: Record<string, string> = {
        '--vscode-sideBar-background':                  '--sidenavBackground',
        '--vscode-sideBar-foreground':                  '--toolboxColor',
        '--vscode-sideBar-border':                      '--toolboxBorder',
        '--vscode-editorGroupHeader-tabsBackground':    '--workPanelBackground',
        '--vscode-titleBar-activeBackground':           '--headerBackground',
        '--vscode-titleBar-activeForeground':           '--headerColor',
        '--vscode-titleBar-border':                     '--headerBorder',
        '--vscode-button-background':                   '--toolboxButton',
        '--vscode-button-foreground':                   '--toolboxItemActiveColor',
        '--vscode-input-background':                    '--formInputBackground',
        '--vscode-input-foreground':                    '--formInputColor',
        '--vscode-focusBorder':                         '--formInputBorderFocus',
        '--vscode-panel-border':                        '--formSeparatorColor',
        '--vscode-statusBar-background':                '--footZoomBackground',
        '--vscode-statusBar-hoverBackground':           '--footZoomBackgroundHover',
        '--vscode-statusBar-foreground':                '--footZoomColor',
        '--vscode-scrollbarSlider-background':          '--scrollbarTrack',
        '--vscode-scrollbarSlider-hoverBackground':     '--scrollbarThumb',
        '--vscode-badge-background':                    '--chipsBackground',
        '--vscode-editor-background':                   '--svgEditWorkareaBackground',
        '--vscode-editorWidget-background':             '--toolboxBackground',
        '--vscode-menu-background':                     '--svgEditWorkareaContextMenu',
        '--vscode-menu-foreground':                     '--svgEditWorkareaContextColor',
    };

    constructor(@Inject(DOCUMENT) private document: Document) {
        // Listen for VS Code design tokens posted by simulatorEditorPane.js.
        window.addEventListener('message', (event) => {
            if (event.data?.type === 'volt:theme-tokens') {
                this._applyVscodeTokens(event.data.tokens);
            }
        });

        // When embedded in Plaxio (iframe), force dark theme immediately
        // and request tokens from the parent frame
        if (window.parent !== window) {
            this.setTheme(ThemeService.ThemeType.Dark);
            try {
                window.parent.postMessage({ type: 'volt:request-theme' }, '*');
            } catch (_) {}
        }
    }

    static ThemeType = { Dark: 'dark', Default: 'default' };

    private _applyVscodeTokens(vscodeTokens: Record<string, string>) {
        console.log('[volt-theme] FUXA received tokens, sideBar=' + vscodeTokens['--vscode-sideBar-background']);
        // Map VS Code tokens to FUXA vars
        const fuxaOverrides: Record<string, string> = {};
        for (const [vscodeVar, fuxaVar] of Object.entries(ThemeService.VSCODE_TO_FUXA)) {
            const val = vscodeTokens[vscodeVar];
            if (val) fuxaOverrides[fuxaVar] = val;
        }
        // Also accept pre-mapped FUXA vars passed directly (legacy path)
        for (const [k, v] of Object.entries(vscodeTokens)) {
            if (k.startsWith('--') && !k.startsWith('--vscode-')) {
                if (v) fuxaOverrides[k] = v;
            }
        }
        this.voltOverrides = fuxaOverrides;
        this._applyOverridesToDom();
    }

    private _applyOverridesToDom() {
        if (!this.voltOverrides) return;
        const root = this.document.documentElement;
        for (const [k, v] of Object.entries(this.voltOverrides)) {
            if (v) root.style.setProperty(k, v);
        }
        this.document.body.classList.add('dark-theme');
    }

    private _injectMaterialOverrides() {
        const existing = this.document.getElementById('volt-material-override');
        if (existing) existing.remove();

        const v = this.voltOverrides || {};
        const bg        = v['--sidenavBackground']          || '#252526';
        const panelBg   = v['--workPanelBackground']        || '#2d2d2d';
        const fg        = v['--toolboxColor']               || '#cccccc';
        const border    = v['--formSeparatorColor']         || '#3c3c3c';
        const inputBg   = v['--formInputBackground']        || '#3c3c3c';
        const headerBg  = v['--headerBackground']           || '#3c3c3c';
        const btnBg     = v['--toolboxButton']              || '#0e639c';
        const btnFg     = v['--toolboxItemActiveColor']     || '#ffffff';
        const activeBg  = v['--toolboxItemActiveBackground']|| '#094771';
        const style = this.document.createElement('style');
        style.id = 'volt-material-override';
        style.textContent = `
            /* ── Global ── */
            body,html{background:${v['--toolboxBackground']||'#1e1e1e'}!important;color:${fg}!important;}
            /* ── Dialogs ── */
            .mat-mdc-dialog-container,.mdc-dialog__surface,.mat-mdc-dialog-surface{background:${bg}!important;color:${fg}!important;}
            /* ── Menus ── */
            .mat-mdc-select-panel,.mat-mdc-menu-panel,.mdc-menu-surface,.mat-mdc-autocomplete-panel{background:${bg}!important;color:${fg}!important;border:1px solid ${border}!important;}
            /* ── Expansion panels ── */
            .mat-expansion-panel,.mat-mdc-expansion-panel{background:${bg}!important;color:${fg}!important;}
            .mat-expansion-panel-header,.mat-mdc-expansion-panel-header{background:${bg}!important;color:${fg}!important;}
            .mat-expansion-panel-header:hover,.mat-mdc-expansion-panel-header:hover{background:rgba(255,255,255,0.04)!important;}
            .mat-expansion-panel-header-title,.mat-expansion-panel-header-description{color:${fg}!important;}
            .mat-expansion-indicator::after{color:${fg}!important;border-color:${fg}!important;}
            /* ── Tabs ── */
            .mat-mdc-tab-header,.mat-mdc-tab-label-container,.mat-tab-header{background:${bg}!important;border-bottom:1px solid ${border}!important;}
            .mat-mdc-tab,.mdc-tab{color:rgba(255,255,255,0.5)!important;opacity:1!important;}
            .mdc-tab--active .mdc-tab__text-label{color:#ffffff!important;}
            .mdc-tab-indicator__content--underline{border-color:${btnBg}!important;}
            /* ── Toolbar ── */
            .mat-toolbar,.mat-mdc-toolbar,.tools_panel{background:${bg}!important;color:${fg}!important;}
            /* ── Buttons ── */
            .mat-mdc-raised-button.mat-primary,.mat-mdc-unelevated-button.mat-primary,.mat-mdc-flat-button.mat-primary{background:${btnBg}!important;color:${btnFg}!important;}
            .mat-mdc-button,.mat-mdc-icon-button{color:${fg}!important;}
            .mat-mdc-icon-button:hover{background:rgba(255,255,255,0.08)!important;}
            /* ── Options ── */
            .mat-mdc-option{color:${fg}!important;background:transparent!important;}
            .mat-mdc-option:hover,.mat-mdc-option.mat-mdc-option-active,.mat-mdc-option.mdc-list-item--selected{background:${activeBg}!important;color:#ffffff!important;}
            /* ── Inputs ── */
            .mdc-text-field--filled:not(.mdc-text-field--disabled){background:${inputBg}!important;border-radius:2px!important;}
            .mdc-text-field--outlined:not(.mdc-text-field--disabled) .mdc-notched-outline__leading,
            .mdc-text-field--outlined:not(.mdc-text-field--disabled) .mdc-notched-outline__notch,
            .mdc-text-field--outlined:not(.mdc-text-field--disabled) .mdc-notched-outline__trailing{border-color:${border}!important;}
            .mat-mdc-input-element,.mdc-text-field__input{color:${fg}!important;caret-color:${fg}!important;}
            .mat-mdc-form-field-label,.mdc-floating-label{color:#858585!important;}
            /* ── Lists / Cards / Chips ── */
            .mat-mdc-list-item,.mat-list-item{color:${fg}!important;}
            .mat-mdc-card{background:${bg}!important;color:${fg}!important;}
            .mat-mdc-chip{background:${inputBg}!important;color:${fg}!important;border-radius:3px!important;}
            /* ── Dividers ── */
            .mat-divider{border-color:${border}!important;}
            /* ── Tooltips ── */
            .mdc-tooltip__surface,.mat-mdc-tooltip{background:${bg}!important;color:${fg}!important;border:1px solid ${border}!important;border-radius:3px!important;font-size:12px!important;}
            /* ── Scrollbars (VS Code style) ── */
            ::-webkit-scrollbar{width:10px;height:10px;}
            ::-webkit-scrollbar-track{background:transparent!important;}
            ::-webkit-scrollbar-thumb{background:rgba(121,121,121,0.4)!important;border:2px solid transparent;background-clip:content-box;}
            ::-webkit-scrollbar-thumb:hover{background:rgba(100,100,100,0.7)!important;background-clip:content-box;}
            ::-webkit-scrollbar-corner{background:transparent!important;}
            /* ── Kill ripple + elevation ── */
            .mat-ripple-element{display:none!important;}
            .mat-elevation-z1,.mat-elevation-z2,.mat-elevation-z3,.mat-elevation-z4,.mat-elevation-z5,.mat-elevation-z6,.mat-elevation-z7,.mat-elevation-z8{box-shadow:none!important;}
        `;
        this.document.head.appendChild(style);
    }

    setVoltOverrides(tokens: Record<string, string>) {
        this._applyVscodeTokens(tokens);
    }

    setTheme(name = ThemeService.ThemeType.Dark) {
        if (!THEMES[name]) {
            name = ThemeService.ThemeType.Dark;
        }
        const theme = THEMES[name];
        Object.keys(theme).forEach((key) => {
            this.document.documentElement.style.setProperty(`--${key}`, theme[key]);
        });

        const body = document.getElementsByTagName('body')[0];
        body.classList.remove('dark-theme');
        if (name === ThemeService.ThemeType.Dark) {
            body.classList.add('dark-theme');
        }

        // Always re-apply VS Code overrides after FUXA's own theme so they always win
        if (this.voltOverrides) {
            this._applyOverridesToDom();
        }
    }
}
