  display: block;
  height: 100%;
}

.header-panel {
  background-color: var(--headerBackground);
  color: var(--headerColor);
  position: absolute;
  top: 0px;
  left: 0px;
  height: 36px;
  width: 100%;
  text-align: center;
  line-height: 36px;
  border-bottom: 1px solid var(--headerBorder);
}
.header-panel mat-icon {
  display: inline-block;
  vertical-align: text-top;
}

.work-panel {
  position: absolute;
  top: 37px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  background-color: var(--workPanelBackground);
  overflow: hidden;
}
.work-panel .container {
  display: flex;
  flex-direction: column;
  min-width: 300px;
  position: absolute;
  bottom: 0px;
  top: 0px;
  left: 0px;
  right: 0px;
  overflow-y: auto;
}
.work-panel .mat-table {
  width: 100%;
  /* min-width: 1560px; */
}
.work-panel .mat-row,
.work-panel .mat-mdc-row,
.work-panel .my-mat-row {
  min-height: 44px !important;
  height: 44px !important;
  border-top: none !important;
  border-bottom: none !important;
}
.work-panel .mat-cell,
.work-panel .mat-mdc-cell,
.work-panel .mdc-data-table__cell {
  font-size: 13px;
  border-top: none !important;
  border-bottom: 1px solid rgb(81, 81, 81) !important;
}
.work-panel .mat-header-row,
.work-panel .mat-mdc-header-row {
  top: 0;
  position: sticky;
  z-index: 10;
  background-color: var(--workPanelBackground);
}
.work-panel .mat-header-cell {
  font-size: 15px;
  position: sticky;
  top: 0;
  z-index: 11;
  background-color: var(--workPanelBackground);
}
.work-panel .mat-column-select {
  overflow: visible;
  flex: 0 0 100px;
}
.work-panel .mat-column-index {
  overflow: visible;
  flex: 0 0 100px;
}
.work-panel .mat-column-name {
  flex: 0 0 200px;
}
.work-panel .mat-column-description {
  flex: 2 1 250px;
